<script setup>
import AuthenticatedLayout from '@/Layouts/AuthenticatedLayout.vue';
import { Head, Link, useForm } from '@inertiajs/vue3';
const props = defineProps({ incident: Object });
const action = useForm({ occurred_at: new Date().toISOString().slice(0,16), description: '' });
const resolution = useForm({ resolution_notes: '' });
const addAction = () => action.post(route('incidents.actions.store', props.incident.id), { preserveScroll: true, onSuccess: () => action.reset('description') });
const resolve = () => resolution.patch(route('incidents.resolve', props.incident.id), { preserveScroll: true });
</script>
<template><Head :title="incident.title" /><AuthenticatedLayout><template #header><div class="flex items-center justify-between"><div><p class="text-xs font-semibold uppercase" :class="incident.status === 'open' ? 'text-red-700' : 'text-emerald-700'">{{ incident.status }} incident</p><h1 class="text-2xl font-semibold">{{ incident.title }}</h1></div><Link :href="route('incidents.print', incident.id)" class="rounded-lg border px-4 py-2 text-sm font-semibold">Print report</Link></div></template><div class="mx-auto grid max-w-6xl gap-6 px-4 py-8 lg:grid-cols-[3fr_2fr]"><div class="space-y-6"><section class="rounded-xl border bg-white p-6 shadow-sm"><h2 class="font-semibold">Incident summary</h2><dl class="mt-4 grid gap-4 sm:grid-cols-2"><div><dt class="text-xs uppercase text-slate-500">Started</dt><dd>{{ new Date(incident.started_at).toLocaleString() }}</dd></div><div><dt class="text-xs uppercase text-slate-500">Location</dt><dd>{{ incident.site?.name || 'Organization-wide' }}<span v-if="incident.asset"> / {{ incident.asset.name }}</span></dd></div></dl><p v-if="incident.improvised_notes" class="mt-4 whitespace-pre-wrap rounded-lg bg-amber-50 p-3 text-sm">{{ incident.improvised_notes }}</p></section><section v-if="incident.playbook_version" class="rounded-xl border bg-white p-6 shadow-sm"><h2 class="font-semibold">Preserved playbook version {{ incident.playbook_version.version }}</h2><ol class="mt-4 space-y-3"><li v-for="(step,index) in incident.playbook_version.steps" :key="index"><p class="font-medium">{{ index + 1 }}. {{ step.title }} <span class="text-xs uppercase text-teal-700">{{ step.role }}</span></p><p class="ml-5 text-sm text-slate-600">{{ step.description }}</p></li></ol></section><section class="rounded-xl border bg-white p-6 shadow-sm"><h2 class="font-semibold">Action timeline</h2><div class="mt-4 divide-y"><div v-for="entry in incident.actions" :key="entry.id" class="py-3"><p>{{ entry.description }}</p><time class="text-xs text-slate-500">{{ new Date(entry.occurred_at).toLocaleString() }}</time></div><p v-if="!incident.actions.length" class="py-6 text-sm text-slate-500">No actions logged yet.</p></div></section></div><aside class="space-y-5"><section class="rounded-xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Attached alerts</h2><div class="mt-3 space-y-2"><div v-for="alert in incident.alerts" :key="alert.id" class="rounded-lg bg-slate-50 p-3"><p class="text-sm font-medium">{{ alert.title }}</p><p class="text-xs uppercase text-slate-500">{{ alert.severity }} / {{ alert.status }}</p></div><p v-if="!incident.alerts.length" class="text-sm text-slate-500">No alerts attached.</p></div></section><form v-if="incident.status === 'open'" @submit.prevent="addAction" class="rounded-xl border bg-white p-5 shadow-sm"><h2 class="font-semibold">Log an action</h2><input v-model="action.occurred_at" type="datetime-local" required class="mt-3 w-full rounded-lg border-slate-300" /><textarea v-model="action.description" required rows="3" class="mt-3 w-full rounded-lg border-slate-300" placeholder="What happened or was done?"></textarea><button class="mt-3 w-full rounded-lg bg-slate-900 px-4 py-2 text-sm font-semibold text-white">Add to timeline</button></form><form v-if="incident.status === 'open'" @submit.prevent="resolve" class="rounded-xl border border-emerald-200 bg-emerald-50 p-5 shadow-sm"><h2 class="font-semibold">Resolve incident</h2><textarea v-model="resolution.resolution_notes" required rows="4" class="mt-3 w-full rounded-lg border-slate-300" placeholder="Final outcome, restoration checks, and follow-up actions"></textarea><button class="mt-3 w-full rounded-lg bg-emerald-700 px-4 py-2 text-sm font-semibold text-white">Mark resolved</button></form><section v-else class="rounded-xl border border-emerald-200 bg-emerald-50 p-5"><h2 class="font-semibold text-emerald-800">Resolution</h2><p class="mt-2 whitespace-pre-wrap text-sm">{{ incident.resolution_notes }}</p></section></aside></div></AuthenticatedLayout></template>
